import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

/** Reconcile a highlighted axis before dereferencing data; -1 means no highlight. */
export function activeIndex(index: number, length: number, fallback = -1) {
  return Number.isInteger(index) && index >= 0 && index < length ? index : length > 0 ? fallback : -1
}

/** Marginalia hangs at inline-end, which is the physical left in RTL. */
export function marginaliaUnder(rect: Pick<DOMRect, "left" | "right">, width: number, direction: string) {
  return (direction === "rtl" ? rect.left : width - rect.right) < 220
}

/** The locale's decimal mark, and a reader for what someone typed: grouping, currency and spaces are ignored. */
export function reader(locale: string) {
  const formatter = new Intl.NumberFormat(locale, { useGrouping: false })
  const decimal = formatter.formatToParts(1.5).find((p) => p.type === "decimal")?.value ?? "."
  const digits = new Map(Array.from({ length: 10 }, (_, n) => [formatter.format(n), String(n)]))
  /** A number, null for nothing typed, undefined for something that isn't a number. */
  return (text: string): number | null | undefined => {
    const normalized = [...text].map((c) => digits.get(c) ?? c).join("")
    const bare = normalized.replace(/[−–]/g, "-").split(decimal).map((s) => s.replace(/[^\d-]/g, "")).join(".")
    if (!/\d/.test(bare)) return /[^\s]/.test(text) ? undefined : null
    const n = Number(bare)
    return Number.isFinite(n) ? n : undefined
  }
}

/** The figures you edit: the locale's decimal mark, no grouping, as many decimals as the number has. */
export const raw = (n: number | null, locale: string) => (n === null ? "" : new Intl.NumberFormat(locale, { useGrouping: false, maximumFractionDigits: 20 }).format(n))

"use client"

import * as React from "react"

function setRef<T>(ref: React.Ref<T> | undefined, node: T | null) {
  if (typeof ref === "function") return ref(node)
  if (ref) ref.current = node
}

/** Each ref keeps its own detach contract: a returned cleanup, or a legacy null call. */
export function composeRefs<T>(own: React.Ref<T> | undefined, forwarded: React.Ref<T> | undefined): React.RefCallback<T> {
  return (node) => {
    const refs = [own, forwarded]
    const cleanups = refs.map((ref) => setRef(ref, node))
    return () => {
      refs.forEach((ref, i) => {
        const cleanup = cleanups[i]
        if (typeof cleanup === "function") cleanup()
        else setRef(ref, null)
      })
    }
  }
}

export function useComposedRefs<T>(own: React.Ref<T> | undefined, forwarded: React.Ref<T> | undefined) {
  return React.useMemo(() => composeRefs(own, forwarded), [own, forwarded])
}

// Roll: the old text leaves one way and the new text arrives from the other,
// like a counter turning over. dir 1 counts up (out the top, in from below);
// -1 counts down. With reduced motion the text simply changes.
import type { ReactNode } from "react"

const turns = new WeakMap<Element, () => void>()
const still = () => typeof matchMedia === "undefined" || matchMedia("(prefers-reduced-motion: reduce)").matches

export function roll(el: HTMLElement, apply: () => void, dist = "0.7em", dir: 1 | -1 = 1) {
  turns.get(el)?.()
  let live = true
  let motion: Animation | undefined
  const cancel = () => {
    live = false
    motion?.cancel()
    if (turns.get(el) === cancel) turns.delete(el)
  }
  turns.set(el, cancel)
  if (still() || !el.animate) {
    apply()
    cancel()
    return cancel
  }
  const up = `-${dist}`
  const down = dist
  motion = el.animate([{ opacity: 1, translate: "0 0" }, { opacity: 0, translate: `0 ${dir > 0 ? up : down}` }], {
    duration: 160,
    easing: "cubic-bezier(.65,0,.35,1)",
    fill: "forwards",
  })
  motion.finished.then(() => {
    if (!live) return
    apply()
    motion?.cancel()
    motion = el.animate([{ opacity: 0, translate: `0 ${dir > 0 ? down : up}` }, { opacity: 1, translate: "0 0" }], {
      duration: 320,
      easing: "cubic-bezier(.16,1,.3,1)",
      fill: "forwards",
    })
    motion.finished.then(cancel, () => {})
  }, () => {})
  return cancel
}

type DigitRollOptions = {
  whole: HTMLElement | null
  figures: (HTMLElement | null)[]
  dir: 1 | -1
  distance?: string
  instant?: boolean
  numeric?: boolean
}

const plain = (value: ReactNode): value is string | number => typeof value === "string" || typeof value === "number"
const digit = /\p{Nd}/u
const number = /^[^\p{L}]*\p{Nd}[^\p{L}]*$/u
const alike = (a: string[], b: string[]) => number.test(a.join("")) && number.test(b.join("")) && a.every((c, i) => digit.test(c) ? digit.test(b[i]) : c === b[i])

/** One owner for the displayed value, pending carries and both halves of every turn. */
export function createDigitRoll(initial: ReactNode, publish: (value: ReactNode) => void) {
  let shown = initial
  let generation = 0
  let pending: ReturnType<typeof setTimeout>[] = []
  let turns: (() => void)[] = []
  const cancel = () => {
    generation++ // invalidate at scheduling time, including work that has not begun to animate
    pending.forEach(clearTimeout)
    turns.forEach((stop) => stop())
    pending = []
    turns = []
  }
  const update = (value: ReactNode, { whole, figures, dir, distance = "0.5em", instant, numeric }: DigitRollOptions) => {
    cancel()
    const mine = generation
    const show = (next: ReactNode) => {
      if (mine !== generation) return
      shown = next
      publish(next)
    }
    if (Object.is(value, shown)) return
    if (instant || still() || !plain(value) || !plain(shown)) return show(value)
    // Compare with what is actually displayed, not the previous (possibly unfinished) request.
    const a = [...String(shown)], b = [...String(value)]
    if (a.length !== b.length || (numeric && !alike(a, b))) {
      if (whole) turns.push(roll(whole, () => show(value), distance, dir))
      else show(value)
      return
    }
    for (let k = b.length - 1, n = 0; k >= 0; k--) {
      if (a[k] === b[k]) continue
      const put = () => {
        const text = [...String(shown)]
        text[k] = b[k]
        show(text.join(""))
      }
      const el = figures[k]
      if (!el) { put(); continue }
      pending.push(setTimeout(() => {
        if (mine === generation) turns.push(roll(el, put, distance, dir))
      }, n++ * 36)) // --db-arpeggio, units first
    }
  }
  return { update, cancel }
}

import type * as React from "react"

// Rove: a group with one tab stop. The arrows move focus to the next or previous item, Home and End jump to the ends;
// right to left, Left and Right follow the page. `round` wraps past the ends, for things set on a circle.
// Chart, line-chart and area-chart walk their points with it (a line, so no wrap); the pie's key and the radar's axes wrap.
const steps: Record<string, 1 | -1> = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 }

export function rove(e: React.KeyboardEvent<HTMLElement>, selector: string, round = false) {
  const items = [...e.currentTarget.querySelectorAll<HTMLElement>(selector)]
  const at = items.indexOf(document.activeElement as HTMLElement)
  const step = steps[e.key]
  if (at < 0 || (!step && e.key !== "Home" && e.key !== "End")) return
  const flip = /^Arrow(Left|Right)$/.test(e.key) && getComputedStyle(e.currentTarget).direction === "rtl" ? -1 : 1
  let to = e.key === "Home" ? 0 : e.key === "End" ? items.length - 1 : at + step * flip
  if (round) to = (to + items.length) % items.length
  if (to < 0 || to >= items.length) return
  e.preventDefault()
  items[to].focus()
}

"use client"

import * as React from "react"

import { createDigitRoll } from "@/lib/0db/roll"

/** Shared counter wheels; a new value or preference change cancels unfinished work. */
export function useDigitRoll(value: React.ReactNode, { order, distance = "0.5em", instant = false, numeric = false }: { order: number | string; distance?: string; instant?: boolean; numeric?: boolean }) {
  const [shown, setShown] = React.useState(value)
  const [roller] = React.useState(() => createDigitRoll(value, setShown))
  const whole = React.useRef<HTMLSpanElement>(null)
  const figs = React.useRef<(HTMLSpanElement | null)[]>([])
  const was = React.useRef(order)
  React.useLayoutEffect(() => {
    const dir = order < was.current ? -1 : 1
    was.current = order
    const preference = matchMedia("(prefers-reduced-motion: reduce)")
    const update = () => roller.update(value, { whole: whole.current, figures: figs.current, dir, distance, numeric, instant: instant || preference.matches })
    update()
    preference.addEventListener("change", update)
    return () => {
      preference.removeEventListener("change", update)
      roller.cancel()
    }
  }, [value, order, distance, instant, numeric, roller])
  return { shown, whole, figs }
}

"use client"

import * as React from "react"

/** Re-read native values after React commits, child changes and the browser's form reset. */
export function useFormPresentation(root: React.RefObject<HTMLElement | null>, sync: () => void) {
  React.useLayoutEffect(sync)
  React.useEffect(() => {
    const el = root.current
    if (!el) return
    let resetTimer = 0
    const watch = new MutationObserver(sync)
    watch.observe(el, { childList: true, characterData: true, subtree: true, attributes: true, attributeFilter: ["value", "checked", "type"] })
    const reset = (event: Event) => {
      if (![...el.querySelectorAll<HTMLInputElement | HTMLTextAreaElement>("input, textarea")].some((control) => control.form === event.target)) return
      // A user-triggered reset can drain microtasks before its default action restores the controls.
      window.clearTimeout(resetTimer)
      resetTimer = window.setTimeout(sync, 0)
    }
    el.ownerDocument.addEventListener("reset", reset, true)
    return () => {
      window.clearTimeout(resetTimer)
      watch.disconnect()
      el.ownerDocument.removeEventListener("reset", reset, true)
    }
  }, [root, sync])
}

/* 0dB · tokens
   The registry:base item. Every component reads only these variables.
   Modes:   <html data-mode="day | nocturne">
   Schemes: <html data-scheme="cotton | blueprint | statue | silence | riso">
   Keys:    <html data-key="ultramarine | viridian | ember | violet">  (overrides the scheme's accent)
   Pairs:   <html data-pair="parma | press | paris | salon"> */

:root {
  color-scheme: light;
  interpolate-size: allow-keywords;

  /* Colour: one note. Ink on paper, one accent for "where you are". */
  --db-paper: #f2f3f0;
  --db-ink: #000;
  --db-graphite: #4a4b50;
  --db-pencil: #6b6c71;
  --db-rule: color-mix(in srgb, var(--db-ink) 14%, transparent);
  --db-rule-strong: color-mix(in srgb, var(--db-ink) 42%, transparent);
  --db-accent: #2b2bee;
  --db-signal: #c8102e;
  --db-mark: #ffe45a;
  --db-on-mark: #000;

  /* Type: the voice (ours) and the expression (yours). */
  --db-voice: "Archivo", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --db-expression: "Bodoni Moda", "Bodoni 72", Didot, Georgia, serif;
  --db-expression-scale: 1.15; /* matches Bodoni's x-height to Archivo's */
  /* Reading grade: the same italic, cut for a line of text. Display keeps its own scale and optical sizing. */
  --db-expression-text-opsz: 6;
  --db-expression-text-variation: "opsz" var(--db-expression-text-opsz);
  --db-expression-text-weight: 500;
  --db-expression-text-tracking: 0.012em;
  --db-expression-text-scale: 1.18;

  /* Dynamics: text steps by a fourth, headings by a fifth. */
  --db-pp: 0.8125rem;   --db-pp-lh: 1.45;  --db-pp-tr: 0.01em;
  --db-p: 1.0625rem;    --db-p-lh: 1.6;    --db-p-tr: 0em;
  --db-mp: 1.375rem;    --db-mp-lh: 1.45;  --db-mp-tr: -0.005em;
  --db-mf: 2rem;        --db-mf-lh: 1.15;  --db-mf-tr: -0.015em;
  --db-f: 3rem;         --db-f-lh: 1.05;   --db-f-tr: -0.025em;
  --db-ff: 4.5rem;      --db-ff-lh: 0.95;  --db-ff-tr: -0.035em;
  --db-fff: clamp(4rem, 11vw, 10rem);       --db-fff-lh: 0.9;  --db-fff-tr: -0.045em;
  --db-ffff: clamp(4rem, 17.5vw, 17rem);  --db-ffff-lh: 0.82; --db-ffff-tr: -0.055em;
  --db-measure: 62ch;

  /* Space: perfect fifths from 8. */
  --db-space-1: 0.25rem;   /*   4 */
  --db-space-2: 0.5rem;    /*   8 */
  --db-space-3: 0.75rem;   /*  12 */
  --db-space-4: 1.125rem;  /*  18 */
  --db-space-5: 1.6875rem; /*  27 */
  --db-space-6: 2.5rem;    /*  40 */
  --db-space-7: 3.75rem;   /*  60 */
  --db-space-8: 5.625rem;  /*  90 */
  --db-space-9: 8.4375rem; /* 135 */
  --db-space-10: 12.5rem;  /* 200 */

  /* Line and shape. */
  --db-hairline: 1px;
  --db-stroke: 1.5px;
  --db-dot: 7px;
  --db-gutter: 24px;
  --db-margin: clamp(20px, 5vw, 80px);

  /* Tempo. */
  --db-allegro: 160ms;   /* hover, press */
  --db-moderato: 320ms;  /* a state changes */
  --db-andante: 640ms;   /* panels, toast, dialog */
  --db-adagio: 1400ms;   /* the overture, once */
  --db-exhale: cubic-bezier(0.16, 1, 0.3, 1);   /* arriving */
  --db-breath: cubic-bezier(0.65, 0, 0.35, 1);  /* moving between states */
  --db-spiccato: cubic-bezier(0.34, 1.5, 0.5, 1); /* landing: a bounced bow, one small rebound */
  --db-arpeggio: 36ms;                           /* the step between things arriving in turn */
}

/* Pairs: a voice (grotesque) and an expression (italic serif). The scale
   lifts each italic until its x-height meets the voice's on the line. */
:root[data-pair="press"] {
  --db-voice: "Schibsted Grotesk", "Helvetica Neue", Arial, sans-serif;
  --db-expression: "Newsreader", Georgia, serif;
  --db-expression-scale: 1.1;
  --db-expression-text-opsz: 6;
  --db-expression-text-variation: "opsz" var(--db-expression-text-opsz);
  --db-expression-text-weight: 500;
  --db-expression-text-tracking: 0.01em;
  --db-expression-text-scale: 1.12;
}
:root[data-pair="paris"] {
  --db-voice: "Instrument Sans", "Helvetica Neue", Arial, sans-serif;
  --db-expression: "EB Garamond", Garamond, Georgia, serif;
  --db-expression-scale: 1.24;
  --db-expression-text-variation: normal; /* Garamond has a weight axis, no optical-size axis. */
  --db-expression-text-weight: 500;
  --db-expression-text-tracking: 0.015em;
  --db-expression-text-scale: 1.3;
}
:root[data-pair="salon"] {
  --db-voice: "Bricolage Grotesque", "Helvetica Neue", Arial, sans-serif;
  --db-expression: "Cormorant", Garamond, Georgia, serif;
  --db-expression-scale: 1.26;
  --db-expression-text-variation: normal; /* Cormorant needs ink and x-height, not an invented axis. */
  --db-expression-text-weight: 600;
  --db-expression-text-tracking: 0.015em;
  --db-expression-text-scale: 1.38;
}

/* Schemes: paper, ink and accent move together; the rules follow the ink. */
:root[data-scheme="blueprint"] { --db-paper: #edf0f7; --db-ink: #0c1b8f; --db-graphite: #2f3b7c; --db-pencil: #58608f; --db-accent: #c23d00; --db-signal: #a3001e; }
:root[data-scheme="statue"]    { --db-paper: #ebeae5; --db-ink: #14213d; --db-graphite: #39445f; --db-pencil: #5f687e; --db-accent: #875600; --db-signal: #b3122e; }
:root[data-scheme="silence"]   { --db-paper: #e2e8e3; --db-ink: #0e2a23; --db-graphite: #32504a; --db-pencil: #4f6962; --db-accent: #1b3de0; --db-signal: #b3122e; }
:root[data-scheme="riso"]      { --db-paper: #f6f5f2; --db-ink: #25286b; --db-graphite: #3f4278; --db-pencil: #636591; --db-accent: #b8005f; --db-signal: #c23c00; }

/* Nocturne: the dark mode, for the long sessions. */
:root[data-mode="nocturne"] {
  color-scheme: dark;
  --db-paper: #10111c;
  --db-ink: #e9eaec;
  --db-graphite: #b4b5bc;
  --db-pencil: #83848c;
  --db-accent: #8c8cff;
  --db-signal: #ff6b7f;
}
:root[data-mode="nocturne"][data-scheme="blueprint"] { --db-paper: #0a1766; --db-ink: #f0f2ff; --db-graphite: #c4caf2; --db-pencil: #929ad0; --db-accent: #ff9557; --db-signal: #ff8a9a; }
:root[data-mode="nocturne"][data-scheme="statue"]    { --db-paper: #0d1528; --db-ink: #eee7d7; --db-graphite: #c7c0b0; --db-pencil: #938d80; --db-accent: #e3b04f; --db-signal: #ff7b86; }
:root[data-mode="nocturne"][data-scheme="silence"]   { --db-paper: #0c1c18; --db-ink: #e1ebe6; --db-graphite: #adc0b9; --db-pencil: #7a918a; --db-accent: #93a6ff; --db-signal: #ff7b86; }
:root[data-mode="nocturne"][data-scheme="riso"]      { --db-paper: #1a1537; --db-ink: #f8eef5; --db-graphite: #d2c6d8; --db-pencil: #9d92ab; --db-accent: #ff62b0; --db-signal: #ffa066; }

/* Keys: the accent can change, the rule doesn't. Declared last so a key wins
   over any scheme. All ≥ 4.5:1 on every paper, by day and in Nocturne. */
:root[data-key="ultramarine"] { --db-accent: #2b2bee; }
:root[data-key="viridian"]    { --db-accent: #0b6e4f; }
:root[data-key="ember"]       { --db-accent: #b83d00; }
:root[data-key="violet"]      { --db-accent: #6a1b9a; }
:root[data-mode="nocturne"][data-key="ultramarine"] { --db-accent: #8c8cff; }
:root[data-mode="nocturne"][data-key="viridian"]    { --db-accent: #4fd1a5; }
:root[data-mode="nocturne"][data-key="ember"]       { --db-accent: #ff8a4c; }
:root[data-mode="nocturne"][data-key="violet"]      { --db-accent: #c58cf2; }

@media (prefers-reduced-motion: reduce) {
  :root {
    --db-allegro: 1ms;
    --db-moderato: 1ms;
    --db-andante: 1ms;
    --db-adagio: 1ms;
    --db-arpeggio: 0ms;
  }
}

/* 0dB · the default pair, Parma. Latin subset, SIL Open Font License 1.1 (see FONT-NOTICES.md). Generated by scripts/build-fonts.mjs. */
@font-face {
  font-family: "Archivo";
  font-style: normal;
  font-display: swap;
  font-weight: 100 900;
  font-stretch: 62% 125%;
  src: url(data:font/woff2;base64,) format("woff2");
  unicode-range: U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;
}
@font-face {
  font-family: "Bodoni Moda";
  font-style: italic;
  font-display: swap;
  font-weight: 400 900;
  src: url(data:font/woff2;base64,) format("woff2");
  unicode-range: U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;
}

/* 0dB · base: the reset, the shared articulations, the type roles and the base pieces
   (link, meta, kbd, corners, fraction) that other items style through. Needs tokens.css first. */
@layer base {
  /* ── base ── */
  *, *::before, *::after { box-sizing: border-box; }
  html { -webkit-text-size-adjust: 100%; text-size-adjust: 100%; }
  body {
    margin: 0;
    background: var(--db-paper);
    color: var(--db-graphite);
    font-family: var(--db-voice);
    font-size: var(--db-p);
    line-height: var(--db-p-lh);
    font-kerning: normal;
    font-optical-sizing: auto;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    transition: background-color var(--db-andante) var(--db-breath), color var(--db-andante) var(--db-breath);
  }
  :where(h1, h2, h3, h4, p, ul, ol, dl, dd, figure, blockquote) { margin: 0; }
  :where(h1, h2, h3, h4) { color: var(--db-ink); font-weight: 400; }
  :where(input, textarea, select, button) { font: inherit; color: inherit; letter-spacing: inherit; }
  :where(input, textarea) { caret-color: var(--db-accent); }
  /* The highlighter: selection, <mark> and a pointed-at link are one thing. Black on yellow, 16:1, in every scheme and mode.
     Selecting inside a highlight reverses to ink, or the selection would vanish into it. */
  ::selection { background: var(--db-mark); color: var(--db-on-mark); -webkit-text-fill-color: var(--db-on-mark); text-shadow: none; }
  :is(mark, .db-link:is(:hover, :focus-visible, [data-force~="hover"], [data-state="open"]), .db-prose a:is(:hover, :focus-visible))::selection,
  :is(mark, .db-link:is(:hover, :focus-visible, [data-force~="hover"], [data-state="open"]), .db-prose a:is(:hover, :focus-visible)) ::selection { background: var(--db-ink); color: var(--db-paper); -webkit-text-fill-color: var(--db-paper); }
  :focus-visible, [data-force~="focus"] { outline: var(--db-stroke) solid var(--db-accent); outline-offset: 4px; }
  mark { background: var(--db-mark); color: var(--db-on-mark); padding-inline: 0.12em; margin-inline: -0.12em; box-decoration-break: clone; -webkit-box-decoration-break: clone; }
  hr { border: 0; height: var(--db-hairline); background: var(--db-rule); margin: 0; }
  [hidden] { display: none !important; } /* components set display; hidden still wins */
  img, svg { display: block; max-width: 100%; }
  /* Scrollbars: a thin stroke on nothing. Pointing at a scroller darkens it from rule to pencil. */
  :root { scrollbar-color: var(--db-rule-strong) transparent; }
  :where(html, body *) { scrollbar-width: thin; }
  :where(.db-scroll, textarea, [role="listbox"]):hover { scrollbar-color: var(--db-pencil) transparent; }
  @supports not (scrollbar-color: auto) {
    /* Safari: the thumb is a hairline down the middle of its gutter, and thickens when pointed at. */
    ::-webkit-scrollbar { width: 11px; height: 11px; background: transparent; }
    ::-webkit-scrollbar-thumb { background: linear-gradient(var(--db-rule-strong) 0 0) center / 2px 100% no-repeat; }
    ::-webkit-scrollbar-thumb:horizontal { background-size: 100% 2px; }
    ::-webkit-scrollbar-thumb:hover { background-image: linear-gradient(var(--db-pencil) 0 0); background-size: 5px 100%; }
    ::-webkit-scrollbar-thumb:horizontal:hover { background-size: 100% 5px; }
    ::-webkit-scrollbar-corner { background: transparent; }
  }

  /* ── motion ── the shared articulations. Pointing sketches (pencil, a hairline,
     a ring); choosing inks (the accent, a fill), and inked things land with
     one small rebound. Strokes leave the way they were heading. */
  @keyframes db-arrive { from { opacity: 0; translate: 0 0.3em; } }
  @keyframes db-land   { from { scale: 0.4; } }
  @keyframes db-draw-x { from { scale: 0 1; } }
  @keyframes db-draw-y { from { scale: 1 0; } }

  /* Type roles. Ours are roman (the voice); yours are italic (the expression). */
  .db-pp   { font-size: var(--db-pp);   line-height: var(--db-pp-lh);   letter-spacing: var(--db-pp-tr); }
  .db-p    { font-size: var(--db-p);    line-height: var(--db-p-lh);    letter-spacing: var(--db-p-tr); }
  .db-mp   { font-size: var(--db-mp);   line-height: var(--db-mp-lh);   letter-spacing: var(--db-mp-tr); }
  .db-mf   { font-size: var(--db-mf);   line-height: var(--db-mf-lh);   letter-spacing: var(--db-mf-tr); }
  .db-f    { font-size: var(--db-f);    line-height: var(--db-f-lh);    letter-spacing: var(--db-f-tr); }
  .db-ff   { font-size: var(--db-ff);   line-height: var(--db-ff-lh);   letter-spacing: var(--db-ff-tr); }
  .db-fff  { font-size: var(--db-fff);  line-height: var(--db-fff-lh);  letter-spacing: var(--db-fff-tr); }
  .db-ffff { font-size: var(--db-ffff); line-height: var(--db-ffff-lh); letter-spacing: var(--db-ffff-tr); }
  /* .db-term: foreign words and musical terms, italic by old book convention. */
  .db-yours, .db-term {
    font-family: var(--db-expression);
    font-style: italic;
    font-weight: 400;
    font-size: calc(var(--db-expression-scale) * 1em);
    line-height: 1;
    letter-spacing: 0;
  }
  .db-label { font-size: var(--db-pp); line-height: var(--db-pp-lh); letter-spacing: var(--db-pp-tr); font-weight: 500; color: var(--db-graphite); }
  .db-figures { font-variant-numeric: tabular-nums lining-nums; }
