    position: absolute !important; width: 1px; height: 1px; padding: 0; margin: -1px;
    overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0;
  }

  /* ── db-link ── one link: a hairline under the words at rest. Pointing draws the highlighter through the whole word, ascenders and
     descenders included, on from the left and off to the right, a pen passing through, and the line gives way to it. Three layers,
     sized together: the top two clipped to the letters (the dark the stroke brings, over the resting colour), then the yellow, so the
     letters turn exactly where the stroke has reached and are never dark on dark. The line is the box's bottom border, clear of the
     descenders and outside the letters' clip, so :visited can recolour it. Focus inks it in the accent under the stroke; pressing
     snaps it back under the stroke in ink. */
  .db-link, .db-prose a {
