  }
  /* Quiet: for a run of links that already reads as links (an index, a programme), the line in rule so the run isn't a barcode. */
  :is(.db-link, .db-prose a)[data-variant="quiet"] { --db-link-line: var(--db-rule-strong); }
  /* Read: the line fades to pencil. (Browsers let :visited change colours only, and keep the unvisited colour's alpha.) */
  :is(.db-link, .db-prose a):is(:visited, [data-force~="visited"]) { border-block-end-color: var(--db-pencil); }
  :is(.db-link, .db-prose a):is(:hover, :focus-visible, [data-force~="hover"], [data-force~="focus"], [data-state="open"]) {
    background-position: 0 0, 0 0, 0 0;
    background-size: 100% 100%, 100% 100%, 100% 100%;
    border-block-end-color: transparent;
    padding-inline: 0.12em; margin-inline: -0.12em; /* the stroke runs 0.12em past each end, like a pen overshooting; the words stay put */
    transition-delay: 0s;
  }
  :is([dir="rtl"], [dir="rtl"] *):is(.db-link, .db-prose a) { background-position: 0 0, 0 0, 0 0; }
  :is([dir="rtl"], [dir="rtl"] *):is(.db-link, .db-prose a):is(:hover, :focus-visible, [data-force~="hover"], [data-force~="focus"], [data-state="open"]) { background-position: 100% 0, 0 0, 100% 0; }
  /* Focus: the stroke, and under it the accent line (the one note of colour: you are here), in place of the outline box. */
  :is(.db-link, .db-prose a):is(:focus-visible, [data-force~="focus"]) { outline: none; border-block-end: var(--db-stroke) solid var(--db-accent); }
