    -webkit-text-fill-color: currentColor; transition: translate var(--db-moderato) var(--db-spiccato);
  }
  :is(.db-link, .db-prose a):is(:hover, :focus-visible, [data-force~="hover"], [data-force~="focus"], [data-state="open"]) .db-link-out { translate: 0.12em -0.12em; }
  :is([dir="rtl"], [dir="rtl"] *) .db-link-out { scale: -1 1; }
  :is([dir="rtl"], [dir="rtl"] *):is(.db-link, .db-prose a):is(:hover, :focus-visible, [data-force~="hover"], [data-force~="focus"], [data-state="open"]) .db-link-out { translate: -0.12em -0.12em; }
  /* reference: after the book's reference marks. No line; a raised mark after the words, in the printer's order (* † ‡ § ‖ ¶,
     then doubled), numbered down the page. The mark is the sign that there's more; pointing strokes the words and the mark. */
  @counter-style db-notes { system: symbolic; symbols: "*" "†" "‡" "§" "‖" "¶"; }
  :root { counter-reset: db-note; }
