  :is(.db-link, .db-prose a)[data-variant="reference"]::after {
    content: counter(db-note, db-notes) / ""; margin-inline-start: 0.06em; font-size: 0.62em; line-height: 0; vertical-align: 0.62em; font-weight: 500;
  }
