  .db-link-addressed { display: inline-flex; flex-wrap: wrap; align-items: baseline; gap: var(--db-space-1) 0.36em; max-inline-size: 100%; }
  .db-link-addressed > .db-link { max-inline-size: 100%; overflow-wrap: anywhere; }
  .db-link-address {
    min-inline-size: 0; overflow-wrap: anywhere; pointer-events: none;
    font-size: max(0.6em, var(--db-pp)); line-height: 1; letter-spacing: 0.02em; color: var(--db-pencil); -webkit-text-fill-color: currentColor;
    clip-path: inset(0 100% 0 0); transition: clip-path var(--db-allegro) var(--db-exhale);
  }
  .db-link-addressed > .db-link:is(:hover, :focus-visible, [data-force~="hover"], [data-force~="focus"], [data-state="open"]) + .db-link-address { clip-path: inset(0); transition-duration: var(--db-moderato); }
  :is([dir="rtl"], [dir="rtl"] *) .db-link-address { clip-path: inset(0 0 0 100%); }
  @media (forced-colors: active) {
    .db-link, .db-prose a { -webkit-text-fill-color: currentColor; background-image: none; border-block-end-color: currentColor; }
    :is(.db-link, .db-prose a):is(:hover, :focus-visible, [data-force~="hover"]) { color: LinkText; border-block-end-color: currentColor; }
    :is(.db-link, .db-prose a):is(:focus-visible, [data-force~="focus"]) { outline: var(--db-stroke) solid LinkText; }
  }

  /* ── db-meta ── a frame row: words held apart by hairlines. The row never wraps, so a hairline can't be left pointing at nothing
     at the end of a line: where the words don't fit, each one stacks in its place, tops level, as the corner notes of a poster do. */
  .db-meta { display: flex; align-items: first baseline; gap: var(--db-space-1) var(--db-space-4); font-size: var(--db-pp); line-height: var(--db-pp-lh); color: var(--db-graphite); }
  .db-meta > :not(hr) { text-wrap: balance; }
  .db-meta > hr { flex: 1; min-width: var(--db-space-4); translate: 0 -0.32em; }
  /* proportional: after the score's proportional (space) notation, where distance is time. Each hairline is as long as the
     interval it stands for (--db-span, set from the component's at), so the silence between the words is to scale. */
  .db-meta[data-variant="proportional"] > hr { flex: var(--db-span, 1) 1 0; min-width: var(--db-space-2); background: var(--db-rule-strong); }
  /* credits: after Ikeda's SPECTRA credits. One rule, and under it small columns hung from it, each a pencil label over its value. */
  .db-meta[data-variant="credits"] { flex-wrap: wrap; align-items: start; gap: var(--db-space-3) var(--db-space-6); padding-block-start: var(--db-space-2); border-block-start: var(--db-hairline) solid var(--db-rule-strong); }
  .db-meta-item { display: grid; gap: 0.1em; }
  .db-meta-label { color: var(--db-pencil); }
  .db-meta-item > :last-child { color: var(--db-ink); font-variant-numeric: tabular-nums lining-nums; }

  /* ── db-kbd ── a key, drawn as the corners of its cap: the frame that doesn't close, as the statement button and the dialog
     wear it, with room inside for the name. Pressing closes it: the corners run together into the whole cap, ink in, and the
     key goes down a little. It sits on the text's baseline, so a key reads as a word in the sentence. */
  .db-kbd {
    --c: var(--db-rule-strong); --l: 0.36em;
    display: inline-grid; place-items: center; box-sizing: border-box; min-width: 2em; height: 2em; padding-inline: 0.55em; white-space: nowrap;
    font: 500 0.78em/1 var(--db-voice); letter-spacing: 0.08em; font-variant-numeric: tabular-nums; color: var(--db-ink); vertical-align: baseline;
    direction: ltr; unicode-bidi: isolate; /* ⌘K reads ⌘K on a right-to-left page too */
    background:
      linear-gradient(var(--c), var(--c)) 0 0 / var(--l) var(--db-hairline),
      linear-gradient(var(--c), var(--c)) 0 0 / var(--db-hairline) var(--l),
      linear-gradient(var(--c), var(--c)) 100% 0 / var(--l) var(--db-hairline),
      linear-gradient(var(--c), var(--c)) 100% 0 / var(--db-hairline) var(--l),
      linear-gradient(var(--c), var(--c)) 0 100% / var(--l) var(--db-hairline),
      linear-gradient(var(--c), var(--c)) 0 100% / var(--db-hairline) var(--l),
      linear-gradient(var(--c), var(--c)) 100% 100% / var(--l) var(--db-hairline),
      linear-gradient(var(--c), var(--c)) 100% 100% / var(--db-hairline) var(--l);
