  /* typewriter: after the round keys of the machine Weingart's letter was typed on, and the dot calendar's discs. The key is a
     ring; pressed, it inks into a disc with the letter reversed out of it in paper, goes down, and lands. */
  .db-kbd[data-variant="typewriter"] {
    background: none; border: var(--db-hairline) solid var(--db-rule-strong); border-radius: 50%; min-width: 2em; height: 2em; padding-inline: 0.55em;
    transition: background-color var(--db-allegro) var(--db-exhale), border-color var(--db-allegro) var(--db-exhale), color var(--db-allegro) var(--db-exhale), translate var(--db-moderato) var(--db-spiccato), scale var(--db-moderato) var(--db-spiccato);
  }
  .db-kbd[data-variant="typewriter"][data-pressed] { background-color: var(--db-ink); border-color: var(--db-ink); color: var(--db-paper); scale: 0.92; transition-duration: 60ms, 60ms, 60ms, var(--db-moderato), var(--db-moderato); }
  /* chord: after the figured bass, where the notes to play with the bass are stacked small beside it. The key stands full size and
     its modifiers are stacked small before it, in one cap: keys held together, read as one. */
  .db-kbd[data-variant="chord"] { grid-auto-flow: column; column-gap: 0.28em; height: auto; min-height: 2em; padding-block: 0.3em; }
  .db-kbd-mods { display: grid; justify-items: end; row-gap: 0.14em; font-size: 0.62em; letter-spacing: 0; color: var(--db-graphite); transition: color var(--db-allegro) var(--db-exhale); }
  .db-kbd-key { font-size: 1.18em; }
