  @media (forced-colors: active) {
    .db-kbd { forced-color-adjust: none; --c: CanvasText; color: CanvasText; }
    .db-kbd[data-variant="typewriter"] { border-color: CanvasText; }
    .db-kbd[data-variant="typewriter"][data-pressed] { background-color: CanvasText; color: Canvas; }
    .db-kbd-mods { color: CanvasText; }
  }

  /* ── db-corners ── four corner marks: a frame that doesn't close.
     Any element with position can wear them; the statement button and the dialog do. */
  :is(.db-corners, .db-btn[data-variant="statement"], .db-dialog)::after {
    --l: var(--db-corner, 8px);
    --c: var(--db-corner-colour, var(--db-ink));
    content: ""; position: absolute; inset: var(--db-corner-inset, 0); pointer-events: none;
    background:
      linear-gradient(var(--c), var(--c)) 0 0 / var(--l) var(--db-hairline),
      linear-gradient(var(--c), var(--c)) 0 0 / var(--db-hairline) var(--l),
      linear-gradient(var(--c), var(--c)) 100% 0 / var(--l) var(--db-hairline),
      linear-gradient(var(--c), var(--c)) 100% 0 / var(--db-hairline) var(--l),
      linear-gradient(var(--c), var(--c)) 0 100% / var(--l) var(--db-hairline),
      linear-gradient(var(--c), var(--c)) 0 100% / var(--db-hairline) var(--l),
      linear-gradient(var(--c), var(--c)) 100% 100% / var(--l) var(--db-hairline),
      linear-gradient(var(--c), var(--c)) 100% 100% / var(--db-hairline) var(--l);
    background-repeat: no-repeat;
  }
  .db-corners { position: relative; }
  /* viewfinder: after the camera's framing marks ("the silence that heals" was shot on a phone). At rest the marks frame the whole;
     point at or focus a part and they glide onto it and lock, with one small rebound. The component sets --db-aim-* from the part. */
  .db-corners[data-variant="viewfinder"] { --aim-pad: 0px; }
  .db-corners[data-variant="viewfinder"][data-aim] { --aim-pad: var(--db-space-2); }
  .db-corners[data-variant="viewfinder"]::after {
    inset: auto; left: calc(var(--db-aim-x, 0px) - var(--aim-pad)); top: calc(var(--db-aim-y, 0px) - var(--aim-pad));
    width: calc(var(--db-aim-w, 100%) + 2 * var(--aim-pad)); height: calc(var(--db-aim-h, 100%) + 2 * var(--aim-pad));
    transition: left var(--db-moderato) var(--db-spiccato), top var(--db-moderato) var(--db-spiccato), width var(--db-moderato) var(--db-spiccato), height var(--db-moderato) var(--db-spiccato);
  }
