  @media (forced-colors: active) { .db-corners[data-variant="viewfinder"]:has(> :focus-visible)::after { --c: Highlight; } }
  /* glide: the viewfinder's marks, lent to a group of controls at any depth (a toolbar, a row of links). At rest there is no
     frame; point at or focus a control and one frame appears round it, then glides from control to control as you move, and
     fades where it last was when you leave. It lands with breath, not the viewfinder's rebound: it is following you, not
     locking on. Arriving from rest it only fades in, so it never flies in from a corner. */
  .db-corners[data-variant="glide"]::after {
