    width: calc(var(--db-aim-w, 0px) + 2 * var(--pad)); height: calc(var(--db-aim-h, 0px) + 2 * var(--pad));
    opacity: 0;
    transition: opacity var(--db-allegro) var(--db-breath), left var(--db-moderato) var(--db-breath), top var(--db-moderato) var(--db-breath), width var(--db-moderato) var(--db-breath), height var(--db-moderato) var(--db-breath);
  }
