  @media (forced-colors: active) { .db-corners[data-variant="glide"]:has(:focus-visible)::after { --c: Highlight; } }
  /* kagi: after the Japanese corner brackets 「 」, where the corner mark is the quotation mark. Only two corners, the opening one
     before the first word and the closing one after the last, however many lines the words run across. */
  .db-corners[data-variant="kagi"] {
    --l: var(--db-corner, 0.42em); --c: var(--db-corner-colour, currentColor);
    position: static; display: inline; quotes: none; padding-inline: 0.3em; box-decoration-break: slice; -webkit-box-decoration-break: slice;
    background:
      linear-gradient(var(--c), var(--c)) 0 0 / var(--l) var(--db-stroke),
      linear-gradient(var(--c), var(--c)) 0 0 / var(--db-stroke) var(--l),
      linear-gradient(var(--c), var(--c)) 100% 100% / var(--l) var(--db-stroke),
      linear-gradient(var(--c), var(--c)) 100% 100% / var(--db-stroke) var(--l);
    background-repeat: no-repeat;
  }
  .db-corners[data-variant="kagi"]::after { content: none; }
