  @media (forced-colors: active) { :is(.db-corners, .db-btn[data-variant="statement"], .db-dialog)::after, .db-corners[data-variant="kagi"] { forced-color-adjust: none; --c: CanvasText; }
    .db-corners[data-variant="kagi"] { color: CanvasText; }
  }

  /* ── db-fraction ── a count set as a display fraction. The part that's yours stands large in the italic, up on the left;
     what it counts toward sits small and upright, a little wide, down on the right, on the same baseline, so the words after
     it ("done") read on one line with both; the solidus between them is a pen stroke, a leaning hairline that thins out at
     both ends and dips just under the line. Pointing inks the stroke and the total. Each figure turns on its own wheel. */
  /* Figures read left to right in a right-to-left page too: the fraction is its own isolated left-to-right run. */
  .db-fraction { display: inline-flex; align-items: baseline; direction: ltr; unicode-bidi: isolate; font-size: var(--db-f); line-height: 0.9; color: var(--db-ink); font-variant-numeric: lining-nums tabular-nums; white-space: nowrap; }
  .db-fraction > i {
    position: relative; align-self: stretch; width: var(--db-hairline); margin-inline: 0.14em 0.08em; rotate: 24deg;
    color: var(--db-rule-strong); background: linear-gradient(transparent, currentColor 22%, currentColor 78%, transparent);
    transition: color var(--db-allegro) var(--db-exhale);
  }
