  .db-fraction > :last-child:not(.db-yours) {
    font-size: max(0.64em, var(--db-pp)); font-weight: 300; font-stretch: 112%; letter-spacing: 0.02em; color: var(--db-graphite);
    transition: color var(--db-allegro) var(--db-exhale);
  }
